+
+RateSequence reattack_scale_sequence(int sample_rate, int midi_note, int note_ms, float gain,
+                                     bool continuous_phase, int phase_degrees,
+                                     double attack_seconds, double release_seconds) {
+  constexpr int kAttackCount = 4;
+  constexpr double kLeadSeconds = 0.2;
+  constexpr double kTailSeconds = 0.2;
+  const double note_seconds = static_cast<double>(note_ms) / 1000.0;
+  const int64_t lead_samples = static_cast<int64_t>(std::llround(kLeadSeconds * sample_rate));
+  const int64_t note_samples = static_cast<int64_t>(std::llround(note_seconds * sample_rate));
+  const int64_t tail_samples = static_cast<int64_t>(std::llround(kTailSeconds * sample_rate));
+  RateSequence sequence;
+  sequence.notes.assign(kAttackCount, midi_note);
+  sequence.samples.assign(
+      static_cast<size_t>(lead_samples + kAttackCount * note_samples + tail_samples), 0.0f);
+  const double fundamental_hz = hz_for_midi(midi_note);
+  const double phase_offset =
+      sonare::constants::kTwoPiD * phase_degrees / sonare::constants::kDegreesPerTurnD;
+  for (int attack = 0; attack < kAttackCount; ++attack) {
+    const int64_t start = lead_samples + static_cast<int64_t>(attack) * note_samples;
+    const double note_start_seconds = static_cast<double>(start - lead_samples) / sample_rate;
+    sequence.onsets.push_back(start);
+    for (int64_t offset = 0; offset < note_samples; ++offset) {
+      const int64_t sample = start + offset;
+      const double local_seconds = static_cast<double>(offset) / sample_rate;
+      const double envelope =
+          std::min({1.0, local_seconds / attack_seconds,
+                    std::max(0.0, note_seconds - local_seconds) / release_seconds});
+      const double carrier_seconds =
+          continuous_phase ? note_start_seconds + local_seconds : local_seconds;
+      const double phase =
+          sonare::constants::kTwoPiD * fundamental_hz * carrier_seconds + phase_offset;
+      double value = 0.0;
+      for (int harmonic = 1; harmonic <= 5; ++harmonic) {
+        value += std::sin(harmonic * phase) / harmonic;
+      }
+      sequence.samples[static_cast<size_t>(sample)] = static_cast<float>(gain * envelope * value);
+    }
+  }
+  return sequence;
+}
+
+sonare::Audio low_register_am_tone(int sample_rate, int amplitude_rate_hz,
+                                   int carrier_phase_quarters, int modulation_phase_quarters) {
+  constexpr double kLeadSeconds = 0.2;
+  constexpr double kBodySeconds = 1.6;
+  constexpr double kTailSeconds = 0.2;
+  constexpr double kAttackSeconds = 0.004;
+  constexpr double kReleaseSeconds = 0.008;
+  constexpr double kFundamentalHz = 110.0;
+  constexpr double kDepth = 0.95;
+  constexpr double kGain = 0.18;
+  const int64_t start = static_cast<int64_t>(std::llround(kLeadSeconds * sample_rate));
+  const int64_t end =
+      static_cast<int64_t>(std::llround((kLeadSeconds + kBodySeconds) * sample_rate));
+  const int64_t total = static_cast<int64_t>(
+      std::llround((kLeadSeconds + kBodySeconds + kTailSeconds) * sample_rate));
+  std::vector<float> samples(static_cast<size_t>(total), 0.0f);
+  const double carrier_offset = sonare::constants::kPiD * carrier_phase_quarters / 2.0;
+  const double modulation_offset = sonare::constants::kPiD * modulation_phase_quarters / 2.0;
+  for (int64_t sample = start; sample < end; ++sample) {
+    const double t = static_cast<double>(sample - start) / sample_rate;
+    const double edge =
+        std::min({1.0, t / kAttackSeconds, std::max(0.0, kBodySeconds - t) / kReleaseSeconds});
+    const double amplitude =
+        1.0 - kDepth * 0.5 *
+                  (1.0 + std::cos(sonare::constants::kTwoPiD * amplitude_rate_hz * t +
+                                  modulation_offset));
+    const double phase = sonare::constants::kTwoPiD * kFundamentalHz * t + carrier_offset;
+    double value = 0.0;
+    for (int harmonic = 1; harmonic <= 5; ++harmonic) {
+      value += std::sin(harmonic * phase) / harmonic;
+    }
+    samples[static_cast<size_t>(sample)] = static_cast<float>(kGain * edge * amplitude * value);
+  }
+  return sonare::Audio::from_buffer(samples.data(), samples.size(), sample_rate);
+}
+
+sonare::Audio scaled_audio(const sonare::Audio& audio, float multiplier) {
+  std::vector<float> samples(audio.begin(), audio.end());
+  for (float& sample : samples) sample *= multiplier;
+  return sonare::Audio::from_vector(std::move(samples), audio.sample_rate());
+}
+
+RateSequence scaled_sequence(RateSequence sequence, float multiplier) {
+  for (float& sample : sequence.samples) sample *= multiplier;
+  return sequence;
+}
+
+void check_transcribed_sequence(const std::vector<TranscribedNote>& actual,
+                                const RateSequence& expected, int sample_rate,
+                                const std::string& context) {
+  INFO(context << ", detected " << actual.size() << " notes");
+  CHECK(actual.size() == expected.notes.size());
+  if (actual.size() != expected.notes.size()) return;
+  for (size_t i = 0; i < actual.size(); ++i) {
+    INFO("note " << i << ": MIDI " << static_cast<int>(actual[i].note) << " vs "
+                 << expected.notes[i] << ", onset " << actual[i].onset_sample << " vs "
+                 << expected.onsets[i]);
+    CHECK(actual[i].note == expected.notes[i]);
+    CHECK(std::abs(sonare::constants::kCentsPerOctave *
+                   std::log2(actual[i].median_hz / hz_for_midi(expected.notes[i]))) <= 50.0);
+    CHECK(std::llabs(actual[i].onset_sample - expected.onsets[i]) * 1000 <= 50LL * sample_rate);
+    CHECK(actual[i].offset_sample - actual[i].onset_sample >=
+          static_cast<int64_t>(std::lround(30.0 * sample_rate / 1000.0)));
+  }
 }

